macro_rules! artifact_functions {
    ($resolver:path, [$(($function:ident, $name:literal)),* $(,)?]) => {
        $(
            #[doc = concat!("The `anvil-", $name, "` source section.")]
            #[must_use]
            pub fn $function() -> Artifact {
                $resolver($name)
            }
        )*
    };
}

