/// Local developer-command execution sections.
pub mod dev {
    use super::{Artifact, CHECKS_JUST_PATH, DEV_CHECK_FILES, named_artifact};

    /// The `anvil-build` execution section.
    #[must_use]
    pub fn build() -> Artifact {
        named_artifact("build", CHECKS_JUST_PATH, DEV_CHECK_FILES)
    }
}

/// All check artifacts in catalog emission order.
#[must_use]
pub(crate) fn check_files() -> Vec<Artifact> {
    file_sections(CHECKS_JUST_PATH, CHECK_FILES)
        .into_iter()
        .chain(file_sections(HELPERS_JUST_PATH, CHECK_HELPER_FILES))
        .chain(file_sections(SETUP_JUST_PATH, CHECK_SETUP_FILES))
        .collect()
}

#[must_use]
pub(crate) fn dev_files() -> Vec<Artifact> {
    vec![dev::build(), setup::dev::build()]
}

/// All group artifacts in catalog emission order.
#[must_use]
pub(crate) fn group_files() -> Vec<Artifact> {
    file_sections(GROUPS_JUST_PATH, GROUP_FILES)
        .into_iter()
        .chain(file_sections(HELPERS_JUST_PATH, GROUP_HELPER_FILES))
        .chain(file_sections(SETUP_JUST_PATH, GROUP_SETUP_FILES))
        .collect()
}

#[cfg(test)]
#[cfg_attr(coverage_nightly, coverage(off))]
mod tests {
    use super::*;
    use crate::Catalog;

    #[test]
    fn source_templates_are_independently_addressable_catalog_sections() {
        let artifact = checks::clippy();
        let Artifact::OwnedFileSection(section) = artifact else {
            panic!("a Just source must be an owned-file section");
        };
        assert_eq!(section.path, CHECKS_JUST_PATH);
        assert_eq!(section.id, "source:justfiles/anvil/checks/clippy.just");
        assert!(section.body.contains("anvil-clippy:"));
        assert!(!section.body.contains("anvil-clippy-setup"));
    }

    #[test]
    fn public_section_apis_return_their_generated_roles() {
        assert!(matches!(
            checks::clippy(),
            Artifact::OwnedFileSection(section) if section.path == CHECKS_JUST_PATH
        ));
        assert!(matches!(
            setup::checks::clippy(),
            Artifact::OwnedFileSection(section) if section.path == SETUP_JUST_PATH
        ));
        assert!(matches!(
            helpers::checks::miri(),
            Artifact::OwnedFileSection(section) if section.path == HELPERS_JUST_PATH
        ));
        assert!(matches!(
            dev::build(),
            Artifact::OwnedFileSection(section) if section.path == CHECKS_JUST_PATH
        ));
        assert!(matches!(
            setup::dev::build(),
            Artifact::OwnedFileSection(section) if section.path == SETUP_JUST_PATH
        ));
        assert!(matches!(
            groups::scheduled_test(),
            Artifact::OwnedFileSection(section) if section.path == GROUPS_JUST_PATH
        ));
        assert!(matches!(
            helpers::groups::scheduled_test(),
            Artifact::OwnedFileSection(section) if section.path == HELPERS_JUST_PATH
        ));
    }

    #[test]
    fn source_sections_are_replaceable_without_affecting_neighbors() {
        let tools = setup::tools();
        let Artifact::OwnedFileSection(section) = &tools else {
            panic!("a Just source must be an owned-file section");
        };
        assert_eq!(section.path, SETUP_JUST_PATH);
        assert_eq!(section.id, "source:justfiles/anvil/setup/tools.just");
        assert!(section.body.contains("_install-component toolchain component:"));

        let neighbor = setup::checks::clippy();
        let replacement = tools.with_body("_install-component toolchain component:\n    echo replaced\n");
        let catalog = Catalog::anvil().into_builder().replace_artifact(replacement).build().unwrap();
        let replaced = catalog
            .artifacts()
            .iter()
            .find(|artifact| {
                matches!(
                    artifact,
                    Artifact::OwnedFileSection(section)
                        if section.path == SETUP_JUST_PATH
                            && section.id == "source:justfiles/anvil/setup/tools.just"
                )
            })
            .expect("the replacement must retain the source identity");
        let unchanged_neighbor = catalog
            .artifacts()
            .iter()
            .find(|artifact| {
                matches!(
                    artifact,
                    Artifact::OwnedFileSection(section)
                        if section.path == SETUP_JUST_PATH
                            && section.id == "source:justfiles/anvil/setup/checks/clippy.just"
                )
            })
            .expect("the neighboring source must remain present");
        assert!(replaced.body().contains("echo replaced"));
        assert_eq!(unchanged_neighbor.body(), neighbor.body());
    }

    #[test]
    fn source_layout_determines_generated_responsibility() {
        for (artifact, expected_path) in [
            (checks::aprz(), CHECKS_JUST_PATH),
            (setup::checks::aprz(), SETUP_JUST_PATH),
            (helpers::checks::miri(), HELPERS_JUST_PATH),
            (groups::pr_fast(), GROUPS_JUST_PATH),
            (setup::groups::pr_fast(), SETUP_JUST_PATH),
            (helpers::groups::scheduled_test(), HELPERS_JUST_PATH),
        ] {
            assert!(
                matches!(artifact, Artifact::OwnedFileSection(section) if section.path == expected_path),
                "artifact must be emitted to {expected_path}"
            );
        }
    }

    #[test]
    fn special_source_sections_keep_their_catalog_identities() {
        for (artifact, expected_path, expected_id) in [
            (checks::impact(), CHECKS_JUST_PATH, "source:justfiles/anvil/checks/impact.just"),
            (groups::tiers(), GROUPS_JUST_PATH, "source:justfiles/anvil/groups/tiers.just"),
            (setup::versions(), SETUP_JUST_PATH, "source:justfiles/anvil/setup/versions.just"),
            (setup::tiers(), SETUP_JUST_PATH, "source:justfiles/anvil/setup/tiers.just"),
            (helpers::common(), HELPERS_JUST_PATH, "source:justfiles/anvil/helpers/common.just"),
            (helpers::impact(), HELPERS_JUST_PATH, "source:justfiles/anvil/helpers/impact.just"),
            (helpers::tiers(), HELPERS_JUST_PATH, "source:justfiles/anvil/helpers/tiers.just"),
        ] {
            assert!(
                matches!(
                    artifact,
                    Artifact::OwnedFileSection(section)
                        if section.path == expected_path && section.id == expected_id
                ),
                "special source must retain {expected_id} in {expected_path}"
            );
        }

        assert!(
            matches!(
                entry(),
                Artifact::OwnedFileSection(section)
                    if section.path == ANVIL_JUST_PATH && section.id == "alias:anvil"
            ),
            "the hub alias must retain its stable section identity"
        );
    }

    #[test]
    fn section_helpers_normalize_line_endings_and_remove_only_the_generated_header() {
        let section = section("generated.just", "test", "first\r\nsecond\r\n");
        let Artifact::OwnedFileSection(section) = section else {
            panic!("section helper must return an owned-file section");
        };
        assert_eq!(section.body, "first\nsecond\n");

        let body = format!("{REPEATED_TEMPLATE_HEADER}recipe:\r\n    echo ok\r\n");
        let artifact = template_section("generated.just", "source.just", &body);
        let Artifact::OwnedFileSection(section) = artifact else {
            panic!("template helper must return an owned-file section");
        };
        assert_eq!(section.body, "recipe:\n    echo ok\n");
    }

    #[test]
    fn generated_headers_and_dev_sections_keep_catalog_order() {
        let identities = |artifacts: Vec<Artifact>| {
            artifacts
                .into_iter()
                .map(|artifact| {
                    let Artifact::OwnedFileSection(section) = artifact else {
                        panic!("catalog ordering helpers must return owned-file sections");
                    };
                    (section.path, section.id)
                })
                .collect::<Vec<_>>()
        };

        assert_eq!(
            identities(headers()),
            [
                (CHECKS_JUST_PATH, "header:checks".to_owned()),
                (GROUPS_JUST_PATH, "header:groups".to_owned()),
                (HELPERS_JUST_PATH, "header:helpers".to_owned()),
                (SETUP_JUST_PATH, "header:setup".to_owned()),
            ]
        );
        assert_eq!(
            identities(dev_files()),
            [
                (CHECKS_JUST_PATH, "source:justfiles/anvil/checks/dev/build.just".to_owned(),),
                (SETUP_JUST_PATH, "source:justfiles/anvil/setup/dev/build.just".to_owned(),),
            ]
        );
    }
}
